CREATE TYPE public.integration_provider AS ENUM ('slack','linear','notion','github','discord','telegram');
CREATE TYPE public.commitment_type AS ENUM ('Side Project (<10h/wk)','Part-Time (10-20h/wk)','Full-Time Co-Founder');
CREATE TYPE public.location_type AS ENUM ('Remote-Only','Hybrid','On-Site');
CREATE TYPE public.pass_reason_type AS ENUM ('stack_mismatch','overqualified','underqualified','time_commitment','no_response','position_filled');
CREATE TABLE public.integration_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,provider public.integration_provider NOT NULL,access_token_encrypted text,webhook_url text,settings_json jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT false, UNIQUE(user_id,provider));
GRANT ALL ON public.integration_settings TO service_role;
ALTER TABLE public.integration_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cofounder_alignment_matrix (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL UNIQUE REFERENCES public.projects(id) ON DELETE CASCADE,equity_range_offered text NOT NULL DEFAULT 'To discuss',vesting_schedule text NOT NULL DEFAULT '4 years, 1-year cliff',time_commitment public.commitment_type NOT NULL DEFAULT 'Part-Time (10-20h/wk)',location_preference public.location_type NOT NULL DEFAULT 'Remote-Only',timezone_overlap_min integer NOT NULL DEFAULT 4 CHECK(timezone_overlap_min BETWEEN 0 AND 24));
GRANT SELECT ON public.cofounder_alignment_matrix TO anon,authenticated;
GRANT INSERT,UPDATE,DELETE ON public.cofounder_alignment_matrix TO authenticated;
GRANT ALL ON public.cofounder_alignment_matrix TO service_role;
ALTER TABLE public.cofounder_alignment_matrix ENABLE ROW LEVEL SECURITY;
CREATE POLICY alignment_public ON public.cofounder_alignment_matrix FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY alignment_owner ON public.cofounder_alignment_matrix FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE TABLE public.match_feedback_loops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),connect_request_id uuid NOT NULL UNIQUE REFERENCES public.connect_requests(id) ON DELETE CASCADE,owner_rating integer CHECK(owner_rating BETWEEN 1 AND 5),pass_reason public.pass_reason_type,feedback_notes text CHECK(length(feedback_notes)<=1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.match_feedback_loops TO authenticated;
GRANT ALL ON public.match_feedback_loops TO service_role;
ALTER TABLE public.match_feedback_loops ENABLE ROW LEVEL SECURITY;
CREATE POLICY feedback_owner ON public.match_feedback_loops FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.connect_requests r JOIN public.projects p ON p.id=r.project_id WHERE r.id=connect_request_id AND p.user_id=auth.uid()));
CREATE TABLE public.builder_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,master_pitch text CHECK(length(master_pitch)<=300),master_role text CHECK(length(master_role)<=80),available boolean NOT NULL DEFAULT true,weekly_digest boolean NOT NULL DEFAULT false,digest_email text,last_digest_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.builder_preferences TO authenticated;
GRANT ALL ON public.builder_preferences TO service_role;
ALTER TABLE public.builder_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_owner ON public.builder_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.builder_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,builder_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,builder_id));
GRANT SELECT ON public.builder_invites TO authenticated;
GRANT ALL ON public.builder_invites TO service_role;
ALTER TABLE public.builder_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_participants ON public.builder_invites FOR SELECT TO authenticated USING(builder_id=auth.uid() OR EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE TABLE public.commitment_checklists(request_id uuid NOT NULL REFERENCES public.connect_requests(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,vesting boolean NOT NULL DEFAULT false,ip_assignment boolean NOT NULL DEFAULT false,time_commitment boolean NOT NULL DEFAULT false,PRIMARY KEY(request_id,user_id));
GRANT SELECT,INSERT,UPDATE ON public.commitment_checklists TO authenticated;
GRANT ALL ON public.commitment_checklists TO service_role;
ALTER TABLE public.commitment_checklists ENABLE ROW LEVEL SECURITY;
CREATE POLICY checklist_participant ON public.commitment_checklists FOR ALL TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.connect_requests r JOIN public.projects p ON p.id=r.project_id WHERE r.id=request_id AND r.status='accepted' AND auth.uid() IN(r.applicant_id,p.user_id))) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.connect_requests r JOIN public.projects p ON p.id=r.project_id WHERE r.id=request_id AND r.status='accepted' AND auth.uid() IN(r.applicant_id,p.user_id)));
CREATE TABLE public.ecosystem_activity(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('pitch','accepted')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ecosystem_activity TO anon,authenticated;
GRANT ALL ON public.ecosystem_activity TO service_role;
ALTER TABLE public.ecosystem_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_public ON public.ecosystem_activity FOR SELECT TO anon,authenticated USING(true);
CREATE INDEX activity_recent ON public.ecosystem_activity(created_at DESC);
CREATE TABLE public.ecosystem_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,request_id uuid NOT NULL REFERENCES public.connect_requests(id) ON DELETE CASCADE,event_type text NOT NULL,completed_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,event_type));
GRANT ALL ON public.ecosystem_outbox TO service_role;
ALTER TABLE public.ecosystem_outbox ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ecosystem_job_state(name text PRIMARY KEY,lease_until timestamptz,paused boolean NOT NULL DEFAULT false,pause_reason text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ecosystem_job_state TO service_role;
ALTER TABLE public.ecosystem_job_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ecosystem_job_items(job_name text NOT NULL,item_key text NOT NULL,completed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_name,item_key));
GRANT ALL ON public.ecosystem_job_items TO service_role;
ALTER TABLE public.ecosystem_job_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.projects ADD COLUMN is_demo boolean NOT NULL DEFAULT false;
GRANT SELECT(is_demo) ON public.profiles TO anon,authenticated;
UPDATE public.profiles SET is_demo=true WHERE id IN('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003');
UPDATE public.projects SET is_demo=true WHERE user_id IS NULL;
CREATE OR REPLACE FUNCTION public.decline_with_feedback(_request_id uuid,_reason public.pass_reason_type,_rating integer DEFAULT NULL,_notes text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.connect_requests r JOIN public.projects p ON p.id=r.project_id WHERE r.id=_request_id AND p.user_id=auth.uid() AND r.status='pending') THEN RAISE EXCEPTION 'Pending pitch not found or not allowed' USING ERRCODE='42501'; END IF;
INSERT INTO public.match_feedback_loops(connect_request_id,owner_rating,pass_reason,feedback_notes) VALUES(_request_id,_rating,_reason,_notes) ON CONFLICT(connect_request_id) DO UPDATE SET owner_rating=excluded.owner_rating,pass_reason=excluded.pass_reason,feedback_notes=excluded.feedback_notes;
UPDATE public.connect_requests SET status='declined' WHERE id=_request_id;
END $$;
REVOKE ALL ON FUNCTION public.decline_with_feedback(uuid,public.pass_reason_type,integer,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.decline_with_feedback(uuid,public.pass_reason_type,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.invite_builder(_project_id uuid,_builder_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.id=_project_id AND p.user_id=auth.uid() AND NOT p.is_demo AND EXISTS(SELECT 1 FROM public.project_proofs pp WHERE pp.project_id=p.id AND pp.verified)) THEN RAISE EXCEPTION 'Only owners of verified listings can invite' USING ERRCODE='42501'; END IF;
IF _builder_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_builder_id AND verification_status='top_builder' AND NOT is_demo) THEN RAISE EXCEPTION 'Only real top builders can be invited'; END IF;
INSERT INTO public.builder_invites(project_id,builder_id) VALUES(_project_id,_builder_id) ON CONFLICT(project_id,builder_id) DO NOTHING RETURNING id INTO _id;
IF _id IS NOT NULL THEN INSERT INTO public.notifications(user_id,type,title,message) SELECT _builder_id,'new_connect_request','Invited to pitch: '||title,'A founder invited you to apply. Open /p/'||id FROM public.projects WHERE id=_project_id; END IF;
RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.invite_builder(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.invite_builder(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.instant_apply(_project_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b record; _id uuid; BEGIN
SELECT p.verification_status,p.is_demo,bp.master_pitch,bp.master_role INTO b FROM public.profiles p JOIN public.builder_preferences bp ON bp.user_id=p.id WHERE p.id=auth.uid();
IF b.verification_status IS DISTINCT FROM 'top_builder' OR b.is_demo OR length(btrim(coalesce(b.master_pitch,'')))<20 OR length(btrim(coalesce(b.master_role,'')))<2 THEN RAISE EXCEPTION 'Top Builder status and a saved Master Pitch are required' USING ERRCODE='42501'; END IF;
IF EXISTS(SELECT 1 FROM public.projects WHERE id=_project_id AND (user_id=auth.uid() OR is_demo)) THEN RAISE EXCEPTION 'Choose a real project owned by someone else'; END IF;
INSERT INTO public.connect_requests(project_id,applicant_id,role_offered,pitch_sentence) VALUES(_project_id,auth.uid(),b.master_role,b.master_pitch) RETURNING id INTO _id; RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.instant_apply(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.instant_apply(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.ecosystem_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_id uuid; event_name text; BEGIN
IF TG_OP='INSERT' THEN IF new.flagged THEN RETURN new; END IF; event_name:='pitch'; ELSE IF new.status<>'accepted' OR old.status='accepted' THEN RETURN new; END IF; event_name:='accepted'; END IF;
SELECT user_id INTO owner_id FROM public.projects WHERE id=new.project_id;
IF owner_id IS NOT NULL THEN INSERT INTO public.ecosystem_activity(project_id,event_type) VALUES(new.project_id,event_name); INSERT INTO public.ecosystem_outbox(user_id,request_id,event_type) VALUES(owner_id,new.id,event_name) ON CONFLICT DO NOTHING; END IF;
RETURN new; END $$;
CREATE TRIGGER ecosystem_event_insert AFTER INSERT ON public.connect_requests FOR EACH ROW EXECUTE FUNCTION public.ecosystem_event();
CREATE TRIGGER ecosystem_event_update AFTER UPDATE ON public.connect_requests FOR EACH ROW EXECUTE FUNCTION public.ecosystem_event();
ALTER PUBLICATION supabase_realtime ADD TABLE public.ecosystem_activity;
CREATE OR REPLACE FUNCTION public.acquire_ecosystem_job(_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE won text; BEGIN
INSERT INTO public.ecosystem_job_state(name,lease_until) VALUES(_name,now()+interval '10 minutes') ON CONFLICT(name) DO UPDATE SET lease_until=excluded.lease_until,updated_at=now() WHERE NOT ecosystem_job_state.paused AND coalesce(ecosystem_job_state.lease_until,'epoch'::timestamptz)<now() RETURNING name INTO won; RETURN won IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.acquire_ecosystem_job(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.acquire_ecosystem_job(text) TO service_role;
CREATE OR REPLACE FUNCTION public.store_integration_secret(_uid uuid,_provider public.integration_provider,_plaintext text,_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ BEGIN
IF length(_key)<32 THEN RAISE EXCEPTION 'Invalid encryption key'; END IF;
INSERT INTO public.integration_settings(user_id,provider,access_token_encrypted) VALUES(_uid,_provider,encode(pgp_sym_encrypt(_plaintext,_key,'cipher-algo=aes256'),'base64')) ON CONFLICT(user_id,provider) DO UPDATE SET access_token_encrypted=excluded.access_token_encrypted; END $$;
REVOKE ALL ON FUNCTION public.store_integration_secret(uuid,public.integration_provider,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.store_integration_secret(uuid,public.integration_provider,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.read_integration_secret(_uid uuid,_provider public.integration_provider,_key text) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT pgp_sym_decrypt(decode(access_token_encrypted,'base64'),_key) FROM public.integration_settings WHERE user_id=_uid AND provider=_provider $$;
REVOKE ALL ON FUNCTION public.read_integration_secret(uuid,public.integration_provider,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.read_integration_secret(uuid,public.integration_provider,text) TO service_role;
CREATE OR REPLACE FUNCTION public.weekly_builder_matches(_uid uuid) RETURNS TABLE(project_id uuid,title text,score double precision) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
SELECT p.id,p.title,greatest(0,(1-(pe.embedding <=> be.embedding)) - coalesce((SELECT avg(CASE f.pass_reason WHEN 'stack_mismatch' THEN 0.10 WHEN 'underqualified' THEN 0.08 WHEN 'time_commitment' THEN 0.06 ELSE 0 END) FROM public.match_feedback_loops f JOIN public.connect_requests r ON r.id=f.connect_request_id JOIN public.profile_embeddings rejected ON rejected.profile_id=r.applicant_id WHERE r.project_id=p.id AND 1-(rejected.embedding <=> be.embedding)>0.7),0))::double precision
FROM public.projects p JOIN public.project_embeddings pe ON pe.project_id=p.id JOIN public.profile_embeddings be ON be.profile_id=_uid WHERE NOT p.is_demo AND p.user_id IS NOT NULL AND p.user_id<>_uid AND NOT EXISTS(SELECT 1 FROM public.connect_requests r WHERE r.project_id=p.id AND r.applicant_id=_uid) ORDER BY 3 DESC LIMIT 3 $$;
REVOKE ALL ON FUNCTION public.weekly_builder_matches(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.weekly_builder_matches(uuid) TO service_role;